SELECT 'JE_HEADERS' key,
'DESCRIPTION'||'~'||'JE_HEADER_ID'||'~'||'LEDGER_ID'||'~'||'JE_CATEGORY'||'~'||'JE_SOURCE'||'~'||'PERIOD_NAME'||'~'||
'NAME'||'~'||'STATUS'||'~'||'DATE_CREATED'||'~'||'ACCRUAL_REV_FLAG'||'~'||'MULTI_BAL_SEG_FLAG'||'~'||'ACTUAL_FLAG'||'~'||
'CONVERSION_FLAG'||'~'||'DEFAULT_EFFECTIVE_DATE'||'~'||'BALANCED_JE_FLAG'||'~'||'BALANCING_SEGMENT_VALUE'||'~'||
'JE_BATCH_ID'||'~'||'EARLIEST_POSTABLE_DATE'||'~'||'POSTED_DATE'||'~'||'ACCRUAL_REV_EFFECTIVE_DATE'||'~'||'ACCRUAL_REV_CHANGE_SIGN_FLAG'||'~'||
'RUNNING_TOTAL_DR'||'~'||'CREATION_DATE'
||'~'||'RUNNING_TOTAL_CR'||'~'||'RUNNING_TOTAL_ACCOUNTED_DR'||'~'||'CREATED_BY'||'~'||'RUNNING_TOTAL_ACCOUNTED_CR'||'~'||
'LAST_UPDATE_DATE'||'~'||'LAST_UPDATED_BY'||'~'||'LAST_UPDATE_LOGIN'||'~'||'CURRENCY_CONVERSION_DATE'||'~'||'OBJECT_VERSION_NUMBER'||'~'||
'EXTERNAL_REFERENCE'||'~'||'TAX_STATUS_CODE'||'~'||'REFERENCE_DATE'||'~'||'MULTI_CURRENCY_FLAG'||'~'||'POST_MULTI_CURRENCY_FLAG'||'~'||
'GLOBAL_ATTRIBUTE_DATE1'||'~'||'GLOBAL_ATTRIBUTE_DATE2'||'~'||'GLOBAL_ATTRIBUTE_DATE3'||'~'||'GLOBAL_ATTRIBUTE_DATE4'||'~'||'GLOBAL_ATTRIBUTE_DATE5'||'~'||
'CURRENCY_CODE'||'~'||'CURRENCY_CONVERSION_RATE'||'~'||'CURRENCY_CONVERSION_TYPE'||'~'||'POST_CURRENCY_CODE'||'~'||'PARENT_JE_HEADER_ID'||'~'||
'REVERSED_JE_HEADER_ID'||'~'||'ACCRUAL_REV_PERIOD_NAME'||'~'||'ACCRUAL_REV_STATUS'||'~'||'ACCRUAL_REV_JE_HEADER_ID'||'~'||'LEGAL_ENTITY_ID' JE_HEADERS
FROM DUAL
UNION ALL
SELECT 'JE_HEADERS' key,
REPLACE(REPLACE(REPLACE(DESCRIPTION,CHR(10),''),CHR(13),''),'~',' ' )||'~'||JE_HEADER_ID||'~'||LEDGER_ID||'~'||JE_CATEGORY||'~'||JE_SOURCE||'~'||PERIOD_NAME||'~'||REPLACE(NAME,'~','')||'~'||REPLACE(STATUS,'~','')||'~'||DATE_CREATED||'~'||ACCRUAL_REV_FLAG||'~'||MULTI_BAL_SEG_FLAG||'~'||ACTUAL_FLAG||'~'||CONVERSION_FLAG||'~'||DEFAULT_EFFECTIVE_DATE||'~'||BALANCED_JE_FLAG||'~'||BALANCING_SEGMENT_VALUE||'~'||
JE_BATCH_ID||'~'||EARLIEST_POSTABLE_DATE||'~'||POSTED_DATE||'~'||ACCRUAL_REV_EFFECTIVE_DATE||'~'||ACCRUAL_REV_CHANGE_SIGN_FLAG||'~'||RUNNING_TOTAL_DR||'~'||CREATION_DATE||'~'||RUNNING_TOTAL_CR||'~'||RUNNING_TOTAL_ACCOUNTED_DR||'~'||CREATED_BY||'~'||RUNNING_TOTAL_ACCOUNTED_CR||'~'||
LAST_UPDATE_DATE||'~'||LAST_UPDATED_BY||'~'||LAST_UPDATE_LOGIN||'~'||CURRENCY_CONVERSION_DATE||'~'||OBJECT_VERSION_NUMBER||'~'||EXTERNAL_REFERENCE||'~'||TAX_STATUS_CODE||'~'||REFERENCE_DATE||'~'||MULTI_CURRENCY_FLAG||'~'||POST_MULTI_CURRENCY_FLAG||'~'||
GLOBAL_ATTRIBUTE_DATE1||'~'||GLOBAL_ATTRIBUTE_DATE2||'~'||GLOBAL_ATTRIBUTE_DATE3||'~'||GLOBAL_ATTRIBUTE_DATE4||'~'||GLOBAL_ATTRIBUTE_DATE5||'~'||
CURRENCY_CODE||'~'||CURRENCY_CONVERSION_RATE||'~'||CURRENCY_CONVERSION_TYPE||'~'||POST_CURRENCY_CODE||'~'||PARENT_JE_HEADER_ID||'~'||REVERSED_JE_HEADER_ID||'~'||ACCRUAL_REV_PERIOD_NAME||'~'||ACCRUAL_REV_STATUS||'~'||ACCRUAL_REV_JE_HEADER_ID||'~'||LEGAL_ENTITY_ID
FROM GL_JE_HEADERS a
where ((:P_FROM_DATE IS NOT NULL AND :P_TO_DATE IS NOT NULL AND a.last_update_date between :P_FROM_DATE AND :P_TO_DATE) or
			(:P_FROM_DATE IS NULL AND :P_TO_DATE IS NULL AND a.last_update_date > (SELECT MAX(ERH.processstart)
                                         FROM ess_request_history ERH
                                             ,ess_request_property ERP
                                        WHERE ERH.requestid = ERP.requestid
                                          AND ERH.definition = 'JobDefinition://oracle/apps/ess/custom/cclf/CCLF_DL_GL_Headers'
                                          AND ERH.executable_status = 'SUCCEEDED'
                                          AND ERP.name = 'submit.argument1'
                             	          AND ERP.value IS NULL)))